import{_ as i}from"./chunks/screenshot-placeholder.DKyzYp9t.js";import{_ as e,o as n,c as r,a6 as l}from"./chunks/framework.DycQjAfF.js";const c=JSON.parse('{"title":"Membaca Kode & Spesifikasi","description":"Menguraikan nomor material, deskripsi, dan lokasi pada label, lalu mencocokkannya dengan barang fisik.","frontmatter":{"title":"Membaca Kode & Spesifikasi","description":"Menguraikan nomor material, deskripsi, dan lokasi pada label, lalu mencocokkannya dengan barang fisik.","status":"ditinjau","dasar":"Standard Penomoran dan Deskripsi Material Cataloguing Warehouse BPI dan materi presentasi Gudang Teknik (slide 11)","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Tutorial","tingkat":"Pemula","sumber":["ik-gudang-teknik","ppt-gudang-teknik"],"kata_kunci":["tutorial","kode barang","nomor material","deskripsi","spesifikasi","label","lokasi","material type","identifikasi","cocokkan","bearing","2RS"]},"headers":[],"relativePath":"tutorial/membaca-kode-barang.md","filePath":"tutorial/membaca-kode-barang.md"}'),t={name:"tutorial/membaca-kode-barang.md"};function o(s,a,d,k,m,u){return n(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="membaca-kode-spesifikasi" tabindex="-1">Membaca Kode &amp; Spesifikasi <a class="header-anchor" href="#membaca-kode-spesifikasi" aria-label="Permalink to &quot;Membaca Kode &amp; Spesifikasi&quot;">​</a></h1><p class="lead">Di latihan ini kamu belajar menguraikan nomor material, deskripsi, dan lokasi pada label, lalu memastikan barang fisik benar-benar sama dengan yang tertulis.</p><div class="tip custom-block"><p class="custom-block-title">Sebelum mulai</p><ul><li><strong>Setelah latihan ini, kamu bisa</strong> menguraikan nomor material sampai ke type, group, dan sub group-nya, membaca deskripsi, lalu mencocokkannya dengan barang.</li><li><strong>Tingkat:</strong> Pemula, sekitar 20 menit.</li><li><strong>Baca dulu:</strong> <a href="/WareHouse/divisi/kode-barang">Kode Barang</a> dan <a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a>.</li><li><strong>Siapkan:</strong> akses ke database barang (minta ke pembimbing), dan satu barang berlabel di gudang.</li></ul></div><h2 id="langkah" tabindex="-1">Langkah <a class="header-anchor" href="#langkah" aria-label="Permalink to &quot;Langkah&quot;">​</a></h2><ol><li><strong>Temukan label.</strong> Cari label pada rak atau kemasan barang. Kalau label tidak ada, berhenti dan laporkan ke pembimbing.</li><li><strong>Baca nomor material per karakter.</strong> Contoh: <code>SA9A00098</code>. Hati-hati, angka 0 dan huruf O mudah tertukar.</li><li><strong>Uraikan nomornya.</strong><ul><li>Huruf pertama adalah <strong>material type</strong>: <code>S</code> berarti stationary &amp; office supply.</li><li>Tiga karakter pertama adalah <strong>group</strong>: <code>SA9</code>.</li><li>Lima karakter pertama adalah <strong>sub group</strong>: <code>SA9A0</code>.</li><li>Empat digit terakhir adalah <strong>nomor urut</strong>: <code>0098</code>.</li></ul></li><li><strong>Baca deskripsinya.</strong> Contoh: <code>FORM;OVERTIME;WORK;F4</code>. Bagian pertama adalah nama utama barang, bagian berikutnya spesifikasinya.</li><li><strong>Baca lokasi dan satuannya.</strong> Contoh: lokasi <code>B.09.02.025</code>, satuan <em>Buku</em>. Cocokkan blok dan areanya dengan <a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a>. Area B.09 memang tempat alat tulis dan perlengkapan kantor.</li><li><strong>Cocokkan dengan master material.</strong> Cari nomor yang sama di master material. Pastikan deskripsi, satuan, dan lokasinya sama dengan label.</li><li><strong>Cocokkan dengan barang fisik.</strong> Periksa tulisan tipe atau ukuran pada barangnya.</li><li><strong>Catat temuan yang tidak cocok</strong>, misalnya label berbeda dengan tulisan di barang, lalu laporkan ke pembimbing.</li></ol><figure><p><img src="'+i+'" alt="Placeholder: foto contoh label barang di rak"></p><figcaption>Placeholder. Ganti dengan foto label barang di Gudang Teknik.</figcaption></figure><h2 id="latihan" tabindex="-1">Latihan <a class="header-anchor" href="#latihan" aria-label="Permalink to &quot;Latihan&quot;">​</a></h2><p>Uraikan data barang berikut, yang diambil dari dokumen Material Reservation Gudang Teknik:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CF3A00010  –  SAFETY EQUIPMENT;EAR PLUGS;ROPE;MAX-30/3301130;100PR/CORDED  –  Set  –  B.04.09.007</span></span></code></pre></div><ol><li>Apa material type barang ini?</li><li>Apa kode group dan sub group-nya?</li><li>Berapa nomor urutnya?</li><li>Di blok dan area mana barang ini disimpan, dan apa isi area itu menurut layout gudang?</li><li>Pada deskripsi <code>BEARING;BALL;6205-2RS</code>, apa arti akhiran <code>2RS</code>?</li></ol><details class="details custom-block"><summary>Lihat jawaban</summary><ol><li><code>C</code>, yaitu consumable.</li><li>Group <code>CF3</code>, sub group <code>CF3A0</code>.</li><li><code>0010</code>.</li><li>Blok B, area 04. Menurut layout, B.04 berisi material parts seperti bearing, lock nut, lock washer, dan perlengkapan keselamatan (<em>safety equipment</em>), jadi cocok untuk ear plug.</li><li>Bearing memakai seal karet di kedua sisinya.</li></ol></details><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Bacakan nomor material dengan suara saat mengambil barang. Cara sederhana ini mengurangi salah ambil.</li><li>Kalau dua barang sangat mirip, bandingkan deskripsinya berdampingan sebelum memilih.</li></ul><h2 id="kesalahan-umum" tabindex="-1">Kesalahan umum <a class="header-anchor" href="#kesalahan-umum" aria-label="Permalink to &quot;Kesalahan umum&quot;">​</a></h2><ul><li>Mencocokkan berdasarkan nama saja tanpa melihat spesifikasinya.</li><li>Menganggap label rak pasti benar, padahal barang bisa saja diletakkan di rak yang salah.</li><li>Membaca nomor material sekilas, sehingga angka 0 tertukar dengan huruf O.</li></ul><h2 id="hasil-yang-diharapkan" tabindex="-1">Hasil yang diharapkan <a class="header-anchor" href="#hasil-yang-diharapkan" aria-label="Permalink to &quot;Hasil yang diharapkan&quot;">​</a></h2><p>Kamu bisa menjelaskan arti setiap bagian nomor material, membaca deskripsi dan lokasinya, dan menemukan setidaknya satu barang yang nomor, deskripsi, dan lokasinya cocok di label, master material, dan barang fisik.</p>',17)])])}const b=e(t,[["render",o]]);export{c as __pageData,b as default};
